function converter(){var a=document.getElementById("tipo").value,r=document.getElementById("ingrediente").value,l=parseFloat(document.getElementById("quantidade").value),c=document.getElementById("resultado"),i={farinha:{xicara:120,colher:15},"açúcar":{xicara:200,colher:12.5},manteiga:{xicara:227,colher:14},leite:{xicara:240,colher:15},oleo:{xicara:218,colher:13.6}};function o(e){return e<.05?"0":(e=Math.round(100*e)/100,Number.isInteger(e)?e.toString():e.toFixed(2))}if(!i[r]||isNaN(l))c.innerText="Preencha os campos corretamente.";else{let e="";var t=i[r];switch(a){case"g_para_xic_colher":e=`<p>${l}g de ${r} equivalem a:</p>
               <ul><li>${o(l/t.xicara)} xícara(s)</li>
                   <li>${o(l/t.colher)} colher(es)</li></ul>`;break;case"xic_para_g_colher":e=`<p>${l} xícara(s) de ${r} equivalem a:</p>
               <ul><li>${o(l*t.xicara)}g</li>
                   <li>${o(l*t.xicara/t.colher)} colher(es)</li></ul>`;break;case"colher_para_g_xic":e=`<p>${l} colher(es) de ${r} equivalem a:</p>
               <ul><li>${o(l*t.colher)}g</li>
                   <li>${o(l*t.colher/t.xicara)} xícara(s)</li></ul>`}c.innerHTML=e}}